candidates.raw:
    // Validate input pointers
    if ((axes == NULL) || (wheel_torque_nm == NULL) || (spacecraft_residual_nm == NULL)) {
        return ADCS_E_NULL;
    }

    // Validate amplitude
    if (!isfinite(amplitude_nm) || amplitude_nm < 0.0) {
        wheel_torque_nm[0] = 0.0;
        wheel_torque_nm[1] = 0.0;
        wheel_torque_nm[2] = 0.0;
        wheel_torque_nm[3] = 0.0;
        spacecraft_residual_nm->x = 0.0;
        spacecraft_residual_nm->y = 0.0;
        spacecraft_residual_nm->z = 0.0;
        return ADCS_E_RANGE;
    }

    // Validate axes: must be finite and unit norm
    adcs_vec3_t sum_axes = {0.0, 0.0, 0.0};
    double norm;
    int i;
    for (i = 0; i < 4; i++) {
        if (!adcs_is_finite_vec3(&axes[i])) {
            wheel_torque_nm[0] = 0.0;
            wheel_torque_nm[1] = 0.0;
            wheel_torque_nm[2] = 0.0;
            wheel_torque_nm[3] = 0.0;
            spacecraft_residual_nm->x = 0.0;
            spacecraft_residual_nm->y = 0.0;
            spacecraft_residual_nm->z = 0.0;
            return ADCS_E_RANGE;
        }

        norm = adcs_vec3_norm(&axes[i]);

        // Check for degenerate (zero) vectors
        if (norm <= ADCS_EPS_NORM) {
            wheel_torque_nm[0] = 0.0;
            wheel_torque_nm[1] = 0.0;
            wheel_torque_nm[2] = 0.0;
            wheel_torque_nm[3] = 0.0;
            spacecraft_residual_nm->x = 0.0;
            spacecraft_residual_nm->y = 0.0;
            spacecraft_residual_nm->z = 0.0;
            return ADCS_E_RANGE;
        }

        // Check for unit norm constraint
        if (fabs(norm - 1.0) > ADCS_EPS_NORM) {
            wheel_torque_nm[0] = 0.0;
            wheel_torque_nm[1] = 0.0;
            wheel_torque_nm[2] = 0.0;
            wheel_torque_nm[3] = 0.0;
            spacecraft_residual_nm->x = 0.0;
            spacecraft_residual_nm->y = 0.0;
            spacecraft_residual_nm->z = 0.0;
            return ADCS_E_RANGE;
        }

        // Accumulate axis vectors for residual calculation
        sum_axes.x += axes[i].x;
        sum_axes.y += axes[i].y;
        sum_axes.z += axes[i].z;
    }

    // Calculate residual spacecraft torque: -sum(axis_i * tau_i)
    // Since tau_i = amplitude_nm for all i:
    spacecraft_residual_nm->x = -amplitude_nm * sum_axes.x;
    spacecraft_residual_nm->y = -amplitude_nm * sum_axes.y;
    spacecraft_residual_nm->z = -amplitude_nm * sum_axes.z;

    // Set equal wheel torques
    wheel_torque_nm[0] = amplitude_nm;
    wheel_torque_nm[1] = amplitude_nm;
    wheel_torque_nm[2] = amplitude_nm;
    wheel_torque_nm[3] = amplitude_nm;

    return ADCS_OK;
}

