candidates.raw:
    // Initialize outputs to zero in case of early exit
    for (int i = 0; i < 4; ++i) {
        wheel_torque_nm[i] = 0.0;
    }
    spacecraft_residual_nm->x = 0.0;
    spacecraft_residual_nm->y = 0.0;
    spacecraft_residual_nm->z = 0.0;

    if ((axes == NULL) || (wheel_torque_nm == NULL) || (spacecraft_residual_nm == NULL)) {
        return ADCS_E_NULL;
    }

    if (!isfinite(amplitude_nm)) {
        return ADCS_E_RANGE;
    }

    adcs_vec3_t axis_sum = {0.0, 0.0, 0.0};
    for (int i = 0; i < 4; ++i) {
        if (!adcs_is_finite_vec3(&axes[i])) {
            return ADCS_E_RANGE;
        }
        double norm = adcs_vec3_norm(&axes[i]);
        if (norm <= ADCS_EPS_NORM) {
            return ADCS_E_RANGE;
        }
        axis_sum = adcs_vec3_add(&axis_sum, &axes[i]);
    }

    for (int i = 0; i < 4; ++i) {
        wheel_torque_nm[i] = amplitude_nm;
    }

    adcs_vec3_t scaled_sum = adcs_vec3_scale(&axis_sum, -amplitude_nm);
    *spacecraft_residual_nm = scaled_sum;

    return ADCS_OK;
}

